-- Migration: backfill customer reward_band from legacy_code.
-- Mapping per codes.csv (code -> tier).

ALTER TABLE customers ADD COLUMN reward_band TEXT;

WITH code_map(code, tier) AS (
  VALUES
    ('A', 'gold'),
    ('B', 'silver'),
    ('C', 'bronze')
)
UPDATE customers
SET reward_band = (
  SELECT tier FROM code_map WHERE code = customers.legacy_code
);
